import{_ as i,l as n,o as a,c,v as t,p as s,x as r,d as p,i as l,S as d}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"模糊检查点","description":"","frontmatter":{"title":"模糊检查点","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fuzzy-checkpoint.md","filePath":"cs/fuzzy-checkpoint.md","lastUpdated":1789023840000}'),h={name:"cs/fuzzy-checkpoint.md"};function E(_,e,u,m,A,f){const o=n("Mermaid");return a(),c("div",null,[e[1]||(e[1]=t('<h1 id="模糊检查点" tabindex="-1">模糊检查点 <a class="header-anchor" href="#模糊检查点" aria-label="Permalink to &quot;模糊检查点&quot;">​</a></h1><div class="epigraph"><p>检查点不冻结世界：记下当时的脏页与活跃事务，后台继续刷；恢复用这份快照当分析起点，而不是要求检查点瞬间数据文件干净。</p><footer>—— 据 Mohan ARIES 检查点；Gray and Reuter；主干 checkpoint 课的模糊补全</footer></div><p><a href="/cs/aries-phases-clr">上一课</a>从检查点 LSN 开分析。本课不写 CLR。缺口是检查点本身：若采取 sharp（停更新、刷光脏页）则吞吐归零。模糊检查点（fuzzy checkpoint）允许检查点期间页继续变脏，只保证记录了「这些页可能脏、这些事务活跃」，redo 仍从足够早的 LSN 开始。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干 <a href="/cs/checkpoint">检查点</a> 缩短恢复。模糊：写 begin-checkpoint，拷贝脏页表与事务表，写 end-checkpoint，再把检查点指针进控制文件。拷贝期间新脏页不在表里？规则是：拷贝后变脏的页，其 recoveryLSN 仍 ≥ 检查点，redo 从检查点前足够早处扫会覆盖。细节在 ARIES：脏页表含当时未刷页。</p><p>缺口是<strong>与刷脏并行</strong>：检查点不代替刷脏；后台写者降低 min recoveryLSN，使下次检查点更紧。两者一起决定 RTO。</p><p><span class="marginnote">模糊不是「随便丢日志」。WAL 仍先于页。检查点只限制崩溃后必须扫描的日志前缀。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>周期或按日志体积触发。太频：写检查点记录与控制文件成为瓶颈。太稀：恢复扫太多。与组提交：检查点 LSN 之前的日志必须已持久。</p><p>复制：备库的 replay 位置类似检查点水位。备份常与检查点对齐拿一致点。</p>',10)),(a(),s(d,null,{default:r(()=>[l(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20BEG%5B%22begin%20checkpoint%22%5D%20--%3E%20SNAP%5B%22%E6%8B%B7%E8%B4%9D%E8%84%8F%E9%A1%B5%E8%A1%A8%20%2F%20%E4%BA%8B%E5%8A%A1%E8%A1%A8%22%5D%0A%20%20SNAP%20--%3E%20END%5B%22end%20checkpoint%22%5D%0A%20%20END%20--%3E%20CTL%5B%22%E6%8E%A7%E5%88%B6%E6%96%87%E4%BB%B6%E6%8C%87%E9%92%88%22%5D%0A%20%20BG%5B%22%E5%90%8E%E5%8F%B0%E5%88%B7%E8%84%8F%22%5D%20--%3E%20MIN%5B%22%E6%8E%A8%E8%BF%9B%20min%20recoveryLSN%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>恢复分析从最近完成的 end-checkpoint 走。半截检查点忽略，用上一个。与 TDE：检查点记录可含密钥版本。与缓冲 2Q：刷脏偏好老脏页，不是刚扫描的一次性页——策略与检查点目标对齐。</p><p>模糊检查点期间的崩溃：未完成检查点无效，正确性靠上一完成点+后续日志。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比生理 vs 逻辑日志粒度。也不把检查点当 vacuum。RTO 课把时间预算量化。</p><p>后课默认：生产用模糊检查点+后台刷脏。日志粒度：记字节差、记操作、还是整页。</p><p>检查点是恢复的索引，不是把数据库变成只读。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模糊检查点记录脏页与事务快照，不停机刷光。</li><li>后台刷脏推进 redo 起点；频率权衡恢复与运行。</li><li>日志粒度下一课。</li><li>出处：ARIES；Gray and Reuter；主干 checkpoint。</li></ul>',9))])}const S=i(h,[["render",E]]);export{k as __pageData,S as default};
